const presets=[['Klasické','Jednoduché a hladké.',.11],['Elegantné matné','Hladký povrch bez odleskov.',.16],['Lesklé','Lesk po celej ploche.',.16],['Prírodné','Prirodzená štruktúra papiera.',.21],['S lesklým logom','Leskne sa iba vybraný detail.',.27],['Extra hrubé','Výrazne pevnejšie v ruke.',.42]];
const colors=[['Čierna','#292c31'],['Biela','#fff'],['Červená','#bd4145'],['Modrá','#386ca4'],['Zelená','#3d805e'],['Ružová','#d88da4'],['Oranžová','#dd8737'],['Žltá','#e5c34b']];
const defaults={preset:1,view:'gallery',mode:'simple',foil:'none',side:'front',round:false,core:'Červená',qty:250,speed:'RELAX',country:'Slovensko',size:'85 × 55 mm',print:'Obojstranná tlač',price:null};let state={...defaults};try{state={...defaults,...JSON.parse(localStorage.getItem('expresta-prototype')||'{}')}}catch{}if(!presets[state.preset])state={...defaults};let opener;
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('sk-SK',{style:'currency',currency:'EUR'}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function photo(i,modal=false){return `<div class="photo material-photo"><img src="assets/materials-transparent.png" alt="${presets[i][0]} — ukážka povrchu" style="left:${-(i%3)*100}%;top:${i<3?-17.31:-151.92}%"></div>`}
const surfaces=['Bez povrchovej úpravy','Matný, obe strany','Lesklý, obe strany','Prirodzená štruktúra','Matný + lesklý detail','Viacvrstvové prevedenie'];
function parameters(s=state){const foil=s.foil==='none'?'Bez fólie':(s.foil==='gold'?'Zlatá':'Strieborná')+' · '+({front:'vpredu',back:'vzadu',both:'obe strany'}[s.side]);return '<dl class="parameter-grid">'+[['Tlač',s.print==='Jednostranná tlač'?'Jednostranná, farebná':'Obojstranná, farebná'],['Rozmer',s.size],['Povrch',surfaces[s.preset]],['Rohy',s.round?'Zaoblené':'Rovné'],[s.preset===5?'Jadro':'Fólia',s.preset===5?s.core:foil]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'}
function tip(i){return i===1?'<span class="tip">Náš tip</span>':''}
function ticketCuts(kind='main',side='vertical'){const modal=kind==='modal',prefix=modal?'modal':'main',fill=modal?'imgVyrez':'imgVyrez',top=modal?'imgVyrezObrys':'imgVyrezObrys1',bottom=modal?'imgVyrezObrys1':'imgVyrezObrys';return '<span class="ticket-cuts '+side+'" aria-hidden="true"><span class="cut first"><img src="assets/'+prefix+'-'+fill+'.svg"><span class="cut-outline"><img src="assets/'+prefix+'-'+top+'.svg"></span></span><span class="cut last"><img src="assets/'+prefix+'-'+fill+'.svg"><span class="cut-outline"><img src="assets/'+prefix+'-'+bottom+'.svg"></span></span></span>'}
function recapCuts(){return '<span class="summary-cut" aria-hidden="true">'+['2','3'].map(n=>'<span><img src="assets/main-imgVyrez1.svg"><span class="outline"><img src="assets/main-imgVyrezObrys'+n+'.svg"></span></span>').join('')+'</span>'} function step(n,label){return '<div class="section-step"><b>'+n+'</b><span>'+label+'</span></div>'}
function gallery(){return `<div class="gallery">${presets.map((p,i)=>`<article class="card ${state.preset===i?'selected':''}"><button class="card-preview" data-material-open="${i}" aria-label="Zväčšiť náhľad: ${p[0]}">${photo(i)}${tip(i)}</button><div class="card-body"><strong>${p[0]}</strong><small>${p[1]}</small><button class="card-select" data-preset="${i}" role="radio" aria-checked="${state.preset===i}" aria-label="Vybrať prevedenie: ${p[0]}"><span class="selection-box">${state.preset===i?'<img src="assets/main-imgFrame.svg" alt="">':''}</span>${state.preset===i?'Vybrané':'Vybrať prevedenie'}</button></div></article>`).join('')}</div>`}
let materialDraft=null;
function draftFor(i){return {...state,preset:i,foil:[3,5].includes(i)?'none':state.foil}}
function renderMaterial(){const i=materialDraft.preset;$('#modal-content').innerHTML=`<h2 id="material-title">Pozrite si prevedenie zblízka</h2><div class="material-layout"><div class="material-carousel" tabindex="0" aria-label="Prevedenia vizitiek" aria-roledescription="carousel">${photo(i,true)}<div class="material-navigation"><button data-material-move="-1" aria-label="Predchádzajúce prevedenie"><img src="assets/modal-imgIconRight.svg" alt=""></button><span aria-live="polite"><b>${presets[i][0]}</b><i></i>${i+1} / 6</span><button data-material-move="1" aria-label="Nasledujúce prevedenie"><img src="assets/modal-imgIconRight.svg" alt=""></button></div></div><div class="material-options"><h4>Prevedenie vizitky</h4>${presets.map((p,j)=>`<button data-material-preset="${j}" class="${i===j?'active':''}" aria-pressed="${i===j}"><img class="variant-radio" src="assets/modal-${i===j?'imgFajka':'imgRadio'}.svg" alt=""><span><b>${p[0]}</b><small>${p[1]}</small></span>${tip(j)}</button>`).join('')}</div></div><div class="material-parameters"><strong class="ticket-name">${presets[i][0]}${ticketCuts('modal')}</strong>${parameters(materialDraft)}</div>${state.foil!=='none'&&materialDraft.foil==='none'?'<p class="material-warning">Toto prevedenie nepodporuje fóliu. Potvrdením sa fólia odstráni.</p>':''}<div class="material-footer"><button class="link" data-action="close"><img src="assets/modal-imgChevron.svg" alt="">Späť na všetky prevedenia</button><span class="footer-space"></span><button class="secondary material-refine" data-action="material-refine">Doladiť vzhľad</button><button class="primary" data-action="material-apply">Vybrať toto prevedenie</button></div>`}
function openMaterial(i){materialDraft=draftFor(i);opener=document.activeElement;$('#modal').classList.add('material-modal');$('#modal').setAttribute('aria-labelledby','material-title');renderMaterial();$('#modal').showModal();$('.close').focus()}
function moveMaterial(i,focus){materialDraft=draftFor((i+6)%6);renderMaterial();$('#modal-content').querySelector(focus)?.focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.materialOpen!==undefined)openMaterial(Number(b.dataset.materialOpen));if(b.dataset.materialPreset!==undefined)moveMaterial(Number(b.dataset.materialPreset),'[data-material-preset="'+b.dataset.materialPreset+'"]');if(b.dataset.materialMove)moveMaterial(materialDraft.preset+Number(b.dataset.materialMove),'[data-material-move="'+b.dataset.materialMove+'"]');if(b.dataset.action==='material-refine'){state={...state,preset:materialDraft.preset,foil:materialDraft.foil,price:null,view:'detail',mode:'simple'};close();render();$('#view-title').setAttribute('tabindex','-1');$('#view-title').focus();$('#view-title').scrollIntoView({block:'start',behavior:'smooth'});return}if(b.dataset.action==='material-apply'){state={...state,preset:materialDraft.preset,foil:materialDraft.foil,price:null};close();render()}});
document.addEventListener('keydown',e=>{if(!materialDraft||!$('#modal').open||!e.target.closest('.material-carousel')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();moveMaterial(materialDraft.preset+(e.key==='ArrowRight'?1:-1),'.material-carousel')});
function discount(qty){return qty>=1000?.5:qty>=500?.25:0}
function quote(qty=state.qty){const rate=presets[state.preset][2]+(state.foil==='none'?0:state.side==='both'?.17:.1)+(state.round?.025:0);return Math.round(((18+qty*rate)*(1-discount(qty))+({RELAX:0,EXPRESS:9.68,'LIGHTNING FAST':32.11}[state.speed]))*100)/100}
function options(items,key,current,extra=''){return `<div class="choices ${extra}">${items.map(([value,label,color])=>`<button class="choice ${current===value?'active':''}" aria-pressed="${current===value}" data-key="${key}" data-value="${value}">${color?`<span class="swatch" style="background:${color}"></span>`:''}${label}</button>`).join('')}</div>`}
function compatible(){return ![3,5].includes(state.preset)}
function details(){return `${state.mode==='simple'?'<button class="link back" data-action="back">‹ Späť na všetky prevedenia</button>':''}${previewCarousel()}<div class="panel">${state.preset===5?`<h4>Farba jadra</h4><p class="small">Farba je viditeľná na hrane vizitky.</p>${options(colors.map(([n,c])=>[n,n,c]),'core',state.core,'cores')}`:compatible()?`<h4>Kovový detail</h4><p class="small">Fólia rozžiari logo alebo vybranú časť grafiky.</p>${options([['none','Bez fólie'],['gold','Zlatá','#c1a15d'],['silver','Strieborná','#b9bdc3']],'foil',state.foil)}${state.foil!=='none'?`<b>Kde bude fólia?</b>${options([['front','Predná strana'],['back','Zadná strana'],['both','Obe strany']],'side',state.side)}<p class="small">Grafiku pre fóliu pridáte v ďalšom kroku.</p>`:''}`:'<h4>Prírodný povrch</h4><p>Prirodzená štruktúra papiera bez laminácie.</p>'}<hr><h4>Tvar rohov</h4>${options([['false','Rovné rohy'],['true','Zaoblené rohy']],'round',String(state.round))}${!compatible()?'<hr><b>Chcete aj fóliu alebo lesklé logo?</b><p class="small">Na tomto drsnom papieri nie sú dostupné. Môžete si vybrať hladké matné prevedenie.</p><button class="link" data-action="conflict">Pozrieť vhodné prevedenie →</button>':'<p class="small">Ďalšie efekty a detailné parametre nájdete v pokročilých nastaveniach.</p>'}</div>${state.mode==='simple'?'<button class="link detail-end" data-action="advanced">Otvoriť pokročilé nastavenia →</button>':''}`}
function select(label,key,values){return `<label>${label}<select data-select="${key}">${values.map(([v,l])=>`<option value="${v}" ${String(state[key])===String(v)?'selected':''}>${l}</option>`).join('')}</select></label>`}
function summaryText(){return [state.preset===5?'Jadro: '+state.core.toLowerCase():state.foil==='none'?'Bez fólie':(state.foil==='gold'?'Zlatá':'Strieborná')+' fólia '+({front:'vpredu',back:'vzadu',both:'na oboch stranách'}[state.side]),state.round?'zaoblené rohy':'rovné rohy'].join(' · ')}
function render(){localStorage.setItem('expresta-prototype',JSON.stringify(state));document.querySelectorAll('.tabs button').forEach(b=>{const active=b.dataset.action===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',active)});$('#view-title').hidden=state.mode==='simple'&&state.view==='gallery';$('#intro').hidden=state.mode==='simple'&&state.view==='gallery';$('#view-title').textContent=state.mode==='advanced'?'Pokročilé nastavenia':state.view==='gallery'?'Aké vizitky sa vám páčia?':'Doladiť vzhľad';$('#intro').textContent=state.mode==='advanced'?'Upravte parametre. Váš výber sa zachová aj pri prepnutí režimu.':state.view==='gallery'?'Vyberte si prevedenie. Papier aj úpravy nastavíme za vás.':'Upravte si detaily. Ostatné parametre zostávajú nastavené za vás.';
$('#content').innerHTML=state.mode==='advanced'?`<div class="panel advanced-grid">${select('Rozmer','size',[['90 × 50 mm','90 × 50 mm'],['85 × 55 mm','85 × 55 mm']])}${select('Tlač','print',[['Obojstranná tlač','Obojstranná tlač'],['Jednostranná tlač','Jednostranná tlač']])}${select('Materiál / prevedenie','preset',presets.map((p,i)=>[i,p[0]]))}<p class="tiny">Prototyp obsahuje parametre navrhnutých prevedení. Úplný výrobný katalóg nie je napojený.</p></div>${details()}`:state.view==='detail'?details():gallery();
$('#selection-summary').innerHTML=`<div class="ticket-preview">${photo(state.preset)}${ticketCuts()}</div><div class="ticket-info"><h2>${presets[state.preset][0]}${tip(state.preset)}</h2>${parameters()}</div><div class="ticket-action">${ticketCuts()}<button class="secondary" data-action="detail">Doladiť vzhľad</button></div>`;
$('#summary').innerHTML=`<section class="summary-section quantity-section">${step('01','Počet kusov')}<label class="label" for="quantity">Koľko kusov potrebujete?</label><div class="counter"><button data-action="minus" aria-label="Znížiť počet"><img src="assets/main-imgIconMinus.svg" alt=""></button><div class="quantity-value"><input id="quantity" style="width:${Math.max(3,String(state.qty).length)}ch" type="number" min="1" max="100000" step="1" value="${state.qty}" aria-describedby="qty-error"><span>ks</span></div><button data-action="plus" aria-label="Zvýšiť počet"><img src="assets/main-imgIconPlus.svg" alt=""></button></div><span class="error" id="qty-error" hidden>Zadajte celé číslo od 1 do 100 000.</span><div class="quick">${[100,250,500,1000].map(n=>`<button class="${state.qty===n?'active':''}" data-key="qty" data-value="${n}">${n.toLocaleString('sk-SK')}${discount(n)?`<small>−${discount(n)*100} %</small>`:''}</button>`).join('')}</div></section><section class="summary-section speeds">${recapCuts()}${step('02','Rýchlosť výroby')}${[['RELAX','⛵','Výhodná cena'],['EXPRESS','🚀','Rýchlejšia výroba'],['LIGHTNING FAST','⚡','Najrýchlejšia výroba']].map(([n,icon,d])=>`<button class="speed ${state.speed===n?'active':''}" aria-pressed="${state.speed===n}" data-key="speed" data-value="${n}"><span class="speed-radio"><img src="assets/${state.speed===n?'modal-imgFajka':'modal-imgRadio'}.svg" alt=""></span><b>${icon} ${n}</b><small>${d}</small>${n!=='RELAX'?`<span class="speed-extra">+${money(n==='EXPRESS'?9.68:32.11)}</span>`:''}</button>`).join('')}<p class="tiny">Výroba začína po schválení grafiky a úhrade.</p></section><section class="summary-section shipping">${recapCuts()}${step('03','Dodanie')}<label for="delivery-country">Krajina doručenia</label><select id="delivery-country" aria-label="Krajina doručenia" data-select="country">${['Slovensko','Česko','Rakúsko','Nemecko','Iná krajina'].map(n=>`<option ${state.country===n?'selected':''}>${n}</option>`).join('')}</select><button class="link" data-action="delivery">Pozrieť kuriérov a časy dodania <img src="assets/main-imgChevron1.svg" alt=""></button></section><section class="summary-section summary-cta">${recapCuts()}${state.price!==null?priceResult():`<button class="primary" data-action="calculate">Vypočítať cenu <img src="assets/main-imgIconCalculatorOrigami.svg" alt=""></button>`}<p class="small">Neviete si vybrať? Radi vám poradíme.</p></section>`;}
function priceResult(){return `<div class="calculated-price" role="status" aria-label="Výsledok výpočtu">${discount(state.qty)?`<span class="discount-badge">Zľava ${discount(state.qty)*100} %</span>`:''}<div class="price-label-row"><span>Cena s DPH</span></div><div class="price-values"><strong>${money(state.price)}</strong><small>${money(state.price/state.qty)} / ks</small></div></div><button class="primary upload-cta" data-action="upload">Nahrať grafiku <img src="assets/main-imgIconCalculatorOrigami.svg" alt=""></button>`}
function update(key,value){state[key]=key==='round'?value==='true':['qty','preset'].includes(key)?Number(value):value;state.price=null;render()}
function choose(i){if([3,5].includes(i)&&state.foil!=='none'){show(`<h2>Zmena prevedenia odstráni fóliu</h2><p>Prevedenie ${presets[i][0]} nepodporuje fóliu. Počet kusov, rozmer, tlač a rýchlosť výroby zostanú.</p><div class="modal-actions"><button class="primary" data-confirm-preset="${i}">Zmeniť prevedenie</button><button class="secondary" data-action="close">Ponechať výber</button></div>`);return}update('preset',i)}
function show(html){$('#modal').classList.remove('material-modal');$('#modal').removeAttribute('aria-labelledby');materialDraft=null;opener=document.activeElement;$('#modal-content').innerHTML=html;$('#modal').showModal();$('.close').focus()}
function close(){ $('#modal').close();materialDraft=null;$('#modal').classList.remove('material-modal');$('#modal').removeAttribute('aria-labelledby');opener?.focus() }
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preset!==undefined){choose(Number(b.dataset.preset));return}if(b.dataset.confirmPreset!==undefined){state.foil='none';close();update('preset',b.dataset.confirmPreset);return}if(b.dataset.key){update(b.dataset.key,b.dataset.value);return}switch(b.dataset.action){case'simple':state.mode='simple';render();break;case'advanced':state.mode='advanced';render();break;case'detail':state.view='detail';render();break;case'back':state.view='gallery';render();break;case'minus':update('qty',Math.max(1,state.qty-50));break;case'plus':update('qty',Math.min(100000,state.qty+50));break;case'reset':state={...defaults};render();break;case'close':close();break;case'upload':show(`<h2>Nahrať grafiku</h2><p>V ďalšom kroku sem zákazník pridá grafiku pre svoje vizitky.</p><p class="small">Toto je ukážka prechodu v prototype. Súbory sa zatiaľ nenahrávajú ani neodosielajú.</p><button class="primary" data-action="close">Späť na kalkuláciu</button>`);break;case'calculate':{const n=Number($('#quantity').value);if(!Number.isInteger(n)||n<1||n>100000){$('#qty-error').hidden=false;$('#quantity').focus();return}state.qty=n;state.price=quote(n);render();break}case'conflict':show(`<h2>Fólia potrebuje iné prevedenie</h2><p>Prepneme na Elegantné matné so zlatou fóliou. Farebné jadro sa odstráni; rozmer, tlač, počet kusov a rýchlosť výroby zostanú.</p><p><b>${presets[state.preset][0]} → Elegantné matné / zlatá fólia</b></p><div class="modal-actions"><button class="primary" data-action="accept">Zmeniť na matné s fóliou</button><button class="secondary" data-action="close">Ponechať výber</button></div>`);break;case'accept':close();state.preset=1;state.foil='gold';state.view='detail';state.price=null;render();break;case'delivery':show(`<h2>Dodanie a kuriéri</h2><b>Krajina doručenia: ${esc(state.country)}</b>${state.country==='Slovensko'?`<p>Orientačný prehľad dopravy</p>${[['Výdajné miesto SPS','1 deň · od 1,99 €'],['Výdajné miesto DPD','1 deň · od 4,49 €'],['Kuriér','1 deň · od 4,99 €'],['DHL Express','1 deň · od 14,49 €'],['Mestský kuriér Bratislava','2 hodiny · od 12,18 €'],['Osobný odber — Squarebizz Bory','Po dokončení výroby · zadarmo']].map(([n,d])=>`<div class="delivery-row"><b>${n}</b><p>${d}</p></div>`).join('')}<p class="tiny">Nadrozmerná doprava: DHL od 60,49 € · Geis od 39,99 €</p>`:'<div class="notice">Pre túto krajinu prototyp nemá cenník dopravy. V živej kalkulačke sa dostupní kuriéri a ceny načítajú podľa krajiny a zásielky.</div>'}<p class="small">Čas prepravy sa pripočítava k času výroby. Konkrétny spôsob doručenia si vyberiete v košíku.</p><p class="tiny">Orientačné údaje z návrhu. Prototyp neoveruje aktuálne ceny ani dostupnosť.</p>`);break}});
document.addEventListener('change',e=>{if(e.target.dataset.select){const key=e.target.dataset.select;if(key==='preset')choose(Number(e.target.value));else update(key,e.target.value)}if(e.target.id==='quantity'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>0&&n<=100000)update('qty',n);else $('#qty-error').hidden=false}});$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});render();
